# Generated by generate_output_schemas.py; do not edit.
"""Readable table lines shared with the generated, standalone skill reader."""


def clean(value):
    return " ".join(str("" if value is None else value).split())


def bounded(text, limit=1500):
    return (
        text
        if len(text.encode()) <= limit
        else text.encode()[: limit - 50].decode("utf-8", "ignore") + "…[超长内容已截断]"
    )


def table_header(table):
    pk = ",".join(table.get("primary_key") or []) or "未声明"
    kind = "视图" if table.get("kind") == "view" else "表"
    return bounded(
        f"[ref: {table['key']}] {table['table']}（{kind} · {clean(table['connection'])} · "
        f"{len(table['columns'])} 列 · PK {pk}）{clean(table.get('comment'))}",
        650,
    )


def column_line(table, column):
    name = column["name"]
    flags = ["PK"] if name in (table.get("primary_key") or []) else []
    for fk in table.get("foreign_keys") or []:
        local = fk.get("constrained_columns") or []
        remote = fk.get("referred_columns") or []
        if name in local:
            index = local.index(name)
            target = ".".join(
                filter(None, [fk.get("referred_schema"), fk.get("referred_table")])
            )
            flags.append(
                "FK→" + target + ("." + remote[index] if index < len(remote) else "")
            )
    nullable = (
        "可空"
        if column.get("nullable")
        else "非空"
        if column.get("nullable") is False
        else "可空性未知"
    )
    return bounded(
        f"[ref: {table['key']}.{name}] {name} · {clean(column.get('type')) or '类型未知'} · "
        f"{','.join(flags) or '—'} · {nullable} · {clean(column.get('comment'))}"
    )


def table_lines(table, columns=None):
    lines = [
        table_header(table),
        f"数据集来源：connection_id={table['connection_id']} schema_name={table.get('schema_name') or '默认'} table_name={table['table_name']}",
        "主键：" + (", ".join(table.get("primary_key") or []) or "未声明"),
    ]
    for fk in table.get("foreign_keys") or []:
        lines.append(
            f"外键：{','.join(fk.get('constrained_columns') or [])} → {fk.get('referred_schema') or ''}.{fk.get('referred_table') or ''}({','.join(fk.get('referred_columns') or [])})"
        )
    lines.extend(
        column_line(table, c) for c in (table["columns"] if columns is None else columns)
    )
    return lines
